from decimal import Decimal
from typing import Any


_SENTINEL_DATE = "00000000"


def _text(value: Any) -> str:
    if value is None:
        return ""
    return str(value)


def _num(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def _field(record: dict, name: str) -> Any:
    return record.get(name, "")


def _nvl(value: Any, default: Any) -> Any:
    if value is None or value == "":
        return default
    return value


def _date_eq(left: Any, right: Any) -> bool:
    left_s = _text(left)
    right_s = _text(right)
    if left_s == _SENTINEL_DATE or right_s == _SENTINEL_DATE:
        return left_s == _SENTINEL_DATE and right_s == _SENTINEL_DATE
    return left_s == right_s


def _date_ge(left: Any, right: Any) -> bool:
    left_s = _text(left)
    right_s = _text(right)
    if left_s == _SENTINEL_DATE or right_s == _SENTINEL_DATE:
        return False
    return left_s >= right_s


def _error(code: str, message: str, severity: str = "BLOCK") -> dict:
    return {
        "code": code,
        "message": message,
        "severity": severity,
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []
    old_record = old if event == "UPDATE" and old is not None else {}

    # OPP-001
    if event in {"INSERT", "UPDATE"}:
        if not (_num(_nvl(_field(record, "AMT"), 0)) >= Decimal("0")):
            errors.append(_error("E3001", "Amount negative"))

    # OPP-002
    if event in {"INSERT", "UPDATE"}:
        if not (
            _text(_field(record, "STAT_CD")) == "W"
            and _num(_nvl(_field(record, "AMT"), 0)) == Decimal("0")
        ):
            pass
        else:
            errors.append(_error("E3002", "Won opportunity requires amount"))

    # OPP-003
    if event in {"INSERT", "UPDATE"}:
        if not (
            _text(_field(record, "STAT_CD")) == "L"
            and _text(_field(record, "LOST_RSN")) == ""
        ):
            pass
        else:
            errors.append(_error("E3003", "Lost reason required"))

    # OPP-004
    if event in {"INSERT", "UPDATE"}:
        if not (
            _text(_field(record, "STAT_CD")) == "W"
            and _date_eq(_field(record, "CLOSE_DT"), _SENTINEL_DATE)
        ):
            pass
        else:
            errors.append(_error("E3004", "Won opportunity requires close date"))

    # OPP-005
    if event == "UPDATE":
        if not (
            _text(_field(old_record, "STAT_CD")) == "W"
            and _text(_field(record, "STAT_CD")) != "W"
        ):
            pass
        else:
            errors.append(_error("E3005", "Cannot reopen a won opportunity"))

    # OPP-006
    if event in {"INSERT", "UPDATE"}:
        status = _text(_field(record, "STAT_CD"))
        stage_pct = _num(_field(record, "STAGE_PCT"))
        consistent = (
            (status == "P" and stage_pct == Decimal("10"))
            or (status == "Q" and stage_pct == Decimal("25"))
            or (status == "N" and stage_pct == Decimal("60"))
            or (status == "W" and stage_pct == Decimal("100"))
            or (status == "L" and stage_pct == Decimal("0"))
        )
        if not consistent:
            errors.append(
                _error("E3006", "Stage percent inconsistent with status")
            )

    # OPP-007
    if event == "INSERT":
        close_dt = _field(record, "CLOSE_DT")
        if not (
            _date_eq(close_dt, _SENTINEL_DATE)
            or _date_ge(close_dt, today)
        ):
            errors.append(
                _error("E3007", "Close date in past", severity="WARN")
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
